class Ellipsis:
    """The Ellipsis API client. `api_key` is a bearer credential from
    app.ellipsis.dev (an API key or a CLI login token)."""

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
        max_retries: int = MAX_RETRIES,
    ) -> None:
        self._transport = Transport(
            api_key=api_key,
            base_url=base_url,
            timeout=timeout,
            max_retries=max_retries,
        )
        self.account = _SyncAccount(self._transport)
        self.agents = _SyncAgents(self._transport)
        self.alerts = _SyncAlerts(self._transport)
        self.auth = _SyncAuth(self._transport)
        self.environments = _SyncEnvironments(self._transport)
        self.handlers = _SyncHandlers(self._transport)
        self.integrations = _SyncIntegrations(self._transport)
        self.reviews = _SyncReviews(self._transport)
        self.secrets = _SyncSecrets(self._transport)
        self.sessions = _SyncSessions(self._transport)
        self.user = _SyncUser(self._transport)
        self.vm_executions = _SyncVmExecutions(self._transport)
        self.vm_images = _SyncVmImages(self._transport)
        self.vms = _SyncVms(self._transport)
        self.webhooks = _SyncWebhooks(self._transport)

    def close(self) -> None:
        self._transport.close()

    def __enter__(self) -> "Ellipsis":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def identity(
        self,
    ) -> models.Identity:
        """Current Identity

        Return the identity behind the caller's credential.

        Any valid credential may call this; no permission grant is needed.

        Required permissions: none; any valid credential.
        API key: Supported.
        CLI user token: Supported.
        Session token: Requires the ellipsis:api scope; no permissions.ellipsis grant is needed.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = "/v1/identity"
        response = self._transport.request("GET", path, response_model=models.Identity)
        assert response is not None
        return response


