    async def update(
        self,
        id: str,
        *,
        archived: Union[bool, None] = None,
        summary: Union[str, None] = None,
    ) -> models.SessionResponse:
        """Update Session

        Archive or unarchive a session, or set its summary, and return it.

        Set archived to true to record the current server time and the
        authenticated GitHub user. API-key requests record no user.
        Repeated archive requests preserve the original time and user.
        Archiving stops the message in progress. An archived session takes
        no messages (409 `session_archived`), and a reply on the Slack
        thread, pull request, issue, or Linear issue it answers starts a
        new session. A session is also archived when it closes and after
        the account's `archive_inactive_sessions_days` without a message.
        When the account sets session log retention, the session's
        records, messages, and prompt are deleted that many days after it
        was archived (`archived.deletes_at`). The session itself stays.

        Set archived to false to clear both fields and let the session
        take messages again. 409 `session_superseded` when a newer session
        now answers the same thread.

        Set summary to name the session. The summary's source becomes
        `user`, and Ellipsis never replaces it with a generated one. With
        both fields, the archive change applies first, and a refused
        archive change leaves the summary as it was.

        Changes are delivered to session and session-list streams.

        Required permissions: write:sessions.
        API key: Supported.
        CLI user token: Supported.
        Session token: Not supported by session tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        Grant match patterns can further restrict access to individual resources.
        """
        path = f"/v1/sessions/{_quote(id)}"
        body_fields: dict[str, Any] = {
            "archived": archived,
            "summary": summary,
        }
        body = build_body(
            models.UpdateSessionRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = await self._transport.request(
            "PUT", path, response_model=models.SessionResponse, json_body=body
        )
        assert response is not None
        return response


